"""Simulate current vs proposed Ski Manager economy on a production snapshot (one winter day, no randomness)."""
import csv, math, sys, statistics as st
from collections import defaultdict

D = sys.argv[1]
def load(name):
    with open(f"{D}/{name}.tsv") as f:
        return list(csv.DictReader(f, delimiter="\t"))

DIFF = {  # rev, cost, vis
    "easy": (1.5, 0.75, 1.3), "standard": (1.0, 1.0, 1.0), "hard": (0.75, 1.3, 0.7),
}
fin = {int(r["user_id"]): r for r in load("fin")}
P = defaultdict(lambda: {"items": [], "tickets": [], "bld": [], "staff": [], "equip": [], "camp": [], "ins": 0, "regs": 0, "scenic": 0, "inc": 0, "exp": 0})
for r in load("items"): P[int(r["user_id"])]["items"].append(r)
for r in load("tickets"): P[int(r["user_id"])]["tickets"].append(r)
for r in load("bld"): P[int(r["user_id"])]["bld"].append(r)
for r in load("staff"): P[int(r["user_id"])]["staff"].append(r)
for r in load("equip"): P[int(r["user_id"])]["equip"].append(r)
for r in load("camp"): P[int(r["user_id"])]["camp"].append(r)
for r in load("ins"): P[int(r["user_id"])]["ins"] += int(r["premium_per_day"])
for r in load("regs"):
    if r["compliant"] == "1": P[int(r["user_id"])]["regs"] += int(r["compliance_cost"])
for r in load("scenic"): P[int(r["user_id"])]["scenic"] += int(r["revenue_per_day"])
for r in load("tx"): P[int(r["user_id"])]["inc" if r["type"] == "income" else "exp"] += int(r["amount"])
LVL = {(r["type_key"], int(r["level"])): r for r in load("lvls")}
ROLE_SALARY = {"ski_patrol": 1500, "instructor": 2000, "mechanic": 1800, "groomer": 1600, "receptionist": 1200,
               "chef": 2200, "medic": 2500, "manager": 3500, "snowmaker": 1700, "park_crew": 1600}

def staff_counts(p):
    a, t = defaultdict(int), defaultdict(int)
    for s in p["staff"]:
        t[s["role"]] += 1
        if s["assigned"] == "1": a[s["role"]] += 1
    return a, t

def common_costs(p, cm, salaries):
    c = salaries * cm
    c += sum(int(b["upkeep_per_day"]) for b in p["bld"] if b["status"] == "open") * cm
    c += sum(int(e["fuel_cost"]) for e in p["equip"] if e["status"] == "active") * cm
    c += sum(int(x["daily_cost"]) for x in p["camp"]) * cm
    c += p["ins"] + p["regs"]
    return c

# ---------------------------------------------------------------- CURRENT
def current(uid, p):
    f = fin[uid]; rm, cm, vm = DIFF.get(f["difficulty"], DIFF["standard"])
    a, t = staff_counts(p)
    slopes = [i for i in p["items"] if i["item_type"] == "slope" and i["status"] == "open"]
    lifts = [i for i in p["items"] if i["item_type"] == "lift" and i["status"] == "open"]
    act = [int(x["price"]) for x in p["tickets"] if x["active"] == "1"]
    avg = sum(act) / len(act) if act else 0
    boost = sum(int(x["visitor_boost"]) for x in p["camp"]) + a["manager"] * 5 + a["instructor"] * 3 + a["ski_patrol"] * 2 + len(slopes) * 2
    vis = round((len(slopes) * 50 + len(lifts) * 30) * (1 + boost / 100) * vm)
    if f["open"] == "0": vis = 0
    inc = vis * avg * 0.6 * rm
    for b in p["bld"]:
        if b["status"] != "open" or f["open"] == "0": continue
        r = int(b["revenue_per_day"])
        if b["building_type"] == "hotel": r *= 1 + a["receptionist"] * 0.15
        if b["building_type"] == "restaurant": r *= 1 + a["chef"] * 0.10
        inc += r * rm
    if a["instructor"] and vis and slopes: inc += min(a["instructor"] * 10, round(vis * 0.08)) * 50 * rm
    inc += p["scenic"] * 0.3 * rm
    sal = sum(int(s["salary"]) for s in p["staff"])
    exp = common_costs(p, cm, sal) + len(lifts) * 30 * 0.15
    return dict(vis=vis, inc=inc, exp=exp)

# ---------------------------------------------------------------- PROPOSED
MIX = {"full_day": .40, "half_day": .15, "child": .12, "senior": .06, "group": .07, "two_day": .10, "weekly": .07, "season": .03}
REF = {"full_day": 55, "half_day": 35, "child": 25, "senior": 40, "group": 45, "two_day": 95, "weekly": 250, "season": 800}
VISITS = {"two_day": 2, "weekly": 6, "season": 25}
ELASTIC = 0.9
LIFT_CAP = {"button": 1000, "chair_fixed": 2400, "chair_detach": 3400, "gondola": 3500, "cable_car": 4000}
LIFT_RUN = {"button": 0.5, "chair_fixed": 0.8, "chair_detach": 1.2, "gondola": 1.8, "cable_car": 2.5}  # EUR per metre per day
SLOPE_RUN = 0.25
SHARE = {"hotel": .20, "restaurant": .70, "rental": .35, "retail": .30, "transportation": .25, "real_estate": .05, "off_season": .03}
STAFF_BONUS = {"hotel": ("receptionist", .15), "restaurant": ("chef", .15)}

def ticket_terms(p, quality=1.0, override=None):
    prices = {x["ticket_type"]: (int(x["price"]), x["active"] == "1") for x in p["tickets"]} or {k: (REF[k], True) for k in REF}
    if override: prices = {k: (override(k), True) for k in REF}
    act = {k: v[0] for k, v in prices.items() if v[1] and k in MIX}
    if not act: return 0, 0
    share = {k: MIX[k] for k in act}
    miss = sum(MIX[k] for k in MIX if k not in act)  # unsold types: those skiers pick the closest on-sale ticket (simplified: spread pro rata)
    tot = sum(share.values())
    share = {k: s + miss * s / tot for k, s in share.items()}
    dem = {k: min(1.5, math.exp(-ELASTIC * (pr / (REF[k] * quality) - 1))) for k, pr in act.items()}
    dmult = sum(share[k] * dem[k] for k in act)
    per_visit = sum(share[k] * dem[k] * act[k] / VISITS.get(k, 1) for k in act) / dmult if dmult else 0
    return dmult, per_visit

def proposed(uid, p, salary_fix=True, override=None):
    f = fin[uid]; rm, cm, vm = DIFF.get(f["difficulty"], DIFF["standard"])
    a, t = staff_counts(p)
    slopes = [i for i in p["items"] if i["item_type"] == "slope" and i["status"] == "open"]
    lifts = [i for i in p["items"] if i["item_type"] == "lift" and i["status"] == "open"]
    diffs = {s["difficulty"] for s in slopes if s["difficulty"] not in ("NULL", "")}
    demand = sum(25 + int(s["length_meters"] or 0) / 50 for s in slopes) * (1 + 0.05 * len(diffs))
    boost = sum(int(x["visitor_boost"]) for x in p["camp"]) + min(a["manager"], 5) * 5 + a["instructor"] * 3 + a["ski_patrol"] * 2 + len(slopes) * 2
    demand *= (1 + boost / 100) * vm
    dmult, per_visit = ticket_terms(p, override=override)
    cap = sum(LIFT_CAP.get(l["subtype"], 2400) * 6 / 10 for l in lifts) or 100  # 6 h, 10 rides each; walk-up only without lifts
    vis = min(round(demand * dmult), round(cap))
    if f["open"] == "0": vis = 0
    inc = vis * per_visit * rm
    # buildings: revenue scales with how full they are
    by_type = defaultdict(list)
    for b in p["bld"]:
        if b["status"] == "open": by_type[b["building_type"]].append(b)
    for typ, bs in by_type.items():
        if typ not in SHARE: continue
        capsum = sum(int(LVL[(typ, int(b["level"]))]["capacity"]) for b in bs)
        util = min(1.0, vis * SHARE[typ] / capsum) if capsum else 0
        rev = sum(int(b["revenue_per_day"]) for b in bs) * util
        if typ in STAFF_BONUS:
            role, pct = STAFF_BONUS[typ]
            rev *= 1 + pct * min(1.0, a[role] / len(bs))
        inc += rev * rm
    if a["instructor"] and vis and slopes: inc += min(a["instructor"] * 10, round(vis * 0.08)) * 50 * rm
    inc += p["scenic"] * 0.3 * rm
    sal = sum(ROLE_SALARY.get(s["role"], int(s["salary"])) if salary_fix else int(s["salary"]) for s in p["staff"])
    run = sum(int(l["length_meters"] or 0) * LIFT_RUN.get(l["subtype"], 0.8) for l in lifts) + sum(int(s["length_meters"] or 0) * SLOPE_RUN for s in slopes)
    exp = common_costs(p, cm, sal) + run * cm
    return dict(vis=vis, inc=inc, exp=exp, run=run, demand=demand, cap=cap)

def pct(xs, q): xs = sorted(xs); return xs[min(len(xs) - 1, int(q * len(xs)))]
def fmt(x): return f"{x/1000:,.1f}k"

