import csv, sys
from collections import defaultdict
D = sys.argv[1]
L = lambda n: list(csv.DictReader(open(f"{D}/{n}.tsv"), delimiter="\t"))
fin = {r["user_id"]: r for r in L("fin")}
real = {u for u, r in fin.items() if r["ustatus"] != "demo" and u != "1"}

# --- proposal ---
T_E, T_W = 0.25, 0.01
LIFT_KWH_PER_M = {"button": 0.4, "chair_fixed": 0.8, "chair_detach": 1.0, "gondola": 1.4, "cable_car": 1.8}
OLD_RUN = {"button": 0.5, "chair_fixed": 0.8, "chair_detach": 1.2, "gondola": 1.8, "cable_car": 2.5}
BLD_KWH = {1: 20, 2: 60, 3: 120}
GUN_KWH, GUN_L = 300, 3800          # catalogue median gun (ta_tt9), water x10
E_SRC = {  # name: (capex, output, upkeep, build_days, max per resort)
    "Grid contract": (5000, 1000, 150, 1, 1), "Diesel generator": (12000, 2000, 350, 2, None),
    "Solar array": (30000, 1500, 15, 4, None), "Wind turbine": (45000, 2500, 60, 6, None)}
W_SRC = {"Deep well": (4000, 8000, 20, 3), "River pump": (6000, 15000, 50, 3),
         "Reservoir": (15000, 25000, 40, 5), "Recycling plant": (25000, 40000, 100, 8)}
print("Energy sources at full use (tariff EUR %.2f/kWh):" % T_E)
for n, (c, o, u, b, m) in E_SRC.items():
    print(f"  {n:16} capex {c:>6,}  {o:>5,} kWh  upkeep {u:>4}  value {o*T_E:>5.0f}  margin {o*T_E-u:>4.0f}/day  payback {c/(o*T_E-u):>3.0f} d")
print("Water sources at full use (tariff EUR %.3f/L):" % T_W)
for n, (c, o, u, b) in W_SRC.items():
    print(f"  {n:16} capex {c:>6,}  {o:>6,} L  upkeep {u:>4}  value {o*T_W:>5.0f}  margin {o*T_W-u:>4.0f}/day  payback {c/(o*T_W-u):>3.0f} d")

# demand per real resort under the proposal
lifts = defaultdict(list); bld = defaultdict(list); guns = defaultdict(int)
for r in L("items"):
    if r["status"] == "open" and r["item_type"] == "lift": lifts[r["user_id"]].append((r["subtype"], int(r["length_meters"] or 0)))
for r in L("bld"):
    if r["status"] == "open": bld[r["user_id"]].append(int(r["level"]))
for r in L("equip"):
    if r["equipment_type"] == "snowmaker" and r["status"] == "active": guns[r["user_id"]] += 1
rows = []
for u in real:
    if not lifts[u] and not bld[u]: continue
    lift_kwh = sum(m * LIFT_KWH_PER_M.get(t, 0.8) for t, m in lifts[u])
    e = lift_kwh + sum(BLD_KWH.get(l, 20) for l in bld[u]) + guns[u] * GUN_KWH
    old_e = len(lifts[u]) * 30 + len(bld[u]) * 20 + guns[u] * GUN_KWH
    w = guns[u] * GUN_L
    old_run = sum(m * OLD_RUN.get(t, 0.8) for t, m in lifts[u])
    new_run = sum(m * (OLD_RUN.get(t, 0.8) - LIFT_KWH_PER_M.get(t, 0.8) * T_E) for t, m in lifts[u])
    rows.append(dict(u=u, e=e, w=w, old_bill=old_e * 0.15 + guns[u] * 380 * 0.002 + old_run, new_bill=e * T_E + w * T_W + new_run, lifts=len(lifts[u]), bld=len(bld[u]), guns=guns[u]))
rows.sort(key=lambda r: r["e"])
def at(q): return rows[min(len(rows)-1, int(q * len(rows)))]
print(f"\nResorts: {len(rows)}. Energy demand and total utility+lift-running bill when importing everything:")
for q, label in ((.25, "p25"), (.5, "median"), (.75, "p75"), (.9, "p90"), (.999, "largest")):
    r = at(q)
    print(f"  {label:7} {r['lifts']} lifts {r['bld']:>3} bld {r['guns']:>2} guns: {r['e']:>7,.0f} kWh {r['w']:>6,} L | bill now {r['old_bill']:>7,.0f} -> proposed {r['new_bill']:>7,.0f}/day")

# best plan for median and p90 resort: greedily add the source with the best payback on the remaining demand
def plan(demand):
    built, left, cap, value = [], demand, 0, 0.0
    counts = defaultdict(int)
    while True:
        best = None
        for n, (c, o, u, b, m) in E_SRC.items():
            if m and counts[n] >= m: continue
            v = min(o, left) * T_E - u
            if v <= 0: continue
            pb = c / v
            if pb <= 90 and (best is None or pb < best[1]): best = (n, pb, c, v, o)
        if not best: break
        n, pb, c, v, o = best
        counts[n] += 1; built.append(f"{n} ({pb:.0f} d)"); left = max(0, left - o); cap += c; value += v
    return built, cap, value
for label, q in (("median", .5), ("p75", .75), ("p90", .9)):
    r = at(q); b, c, v = plan(r["e"])
    print(f"  {label} resort ({r['e']:,.0f} kWh): builds {', '.join(b) or 'nothing'} -> {c:,} capex, saves {v:,.0f}/day, payback {c/v if v else 0:.0f} days")
EOF

